import 'package:firedart/firedart.dart';

Future<void> main() async {
  FirebaseAuth.initialize('YOUR_API_KEY', await HiveStore.create());
  await FirebaseAuth.instance.signIn('email@example.com', 'password');
  var user = await FirebaseAuth.instance.getUser();
  print(user.uid);

  Firestore.initialize('YOUR_PROJECT_ID');
  var users = await Firestore.instance.collection('users').get();
  print(users);
}
